{"begin":"BEGIN_FSV-B19_autopac_generate_SMOKE","stage":"autopac_generate","output":{"generation":{"status":"ok","rego":"package external_pilot

import rego.v1

default allow := false

allow if {
    input.subject.role == "authenticated_api_caller"
    input.action == "POST /api/resource/Purchase Order"
    input.resource.id == "ERPNext:16.0.0"
    not supplier_blocked_for_pos
}

supplier_blocked_for_pos if {
    input.trusted.supplierOnHold == true
    blocking_hold_type
}

blocking_hold_type if {
    input.trusted.holdType == "Invoices"
}

blocking_hold_type if {
    input.trusted.holdType == "All"
}","reason":"Per VIS-FSV-B19-01, when a Supplier is blocked with hold type 'Invoices', ERPNext will not allow Purchase Orders to be created; hold type 'All' applies both Invoice and Payment blocks. The policy allows the POST Purchase Order operation only when the supplier is not on hold or the hold type does not block POs (i.e., not 'Invoices' and not 'All')."},"judge":{"verdict":"ACCEPT","issues":["Policy correctly maps hold types 'Invoices' and 'All' to PO creation denial based on supplier documentation.","Resource.id compared as string against organization schema value 'ERPNext:16.0.0', not object-to-string comparison.","Condition paths used (/trusted/supplierOnHold, /trusted/holdType) are all declared in the runtime ABI and organization schema.","Authentication and other domain validation are left upstream; no extra auth restrictions invented."]}},"end":"END_FSV-B19_autopac_generate_SMOKE"}
